package com.example.taskmanager.controller;
import com.example.taskmanager.dto.*; import com.example.taskmanager.model.User; import com.example.taskmanager.repository.UserRepository; import com.example.taskmanager.security.JwtService; import org.springframework.http.HttpStatus; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.Map;
@RestController @RequestMapping("/api/auth") @CrossOrigin(origins="http://localhost:5173") public class AuthController { final UserRepository repo; final PasswordEncoder enc; final JwtService jwt; public AuthController(UserRepository r,PasswordEncoder e,JwtService j){repo=r;enc=e;jwt=j;} @PostMapping("/register") public Map<String,String> reg(@RequestBody RegisterRequest x){if(repo.findByEmail(x.email()).isPresent())throw new ResponseStatusException(HttpStatus.CONFLICT,"Email already registered");User u=new User();u.setName(x.name());u.setEmail(x.email());u.setPassword(enc.encode(x.password()));repo.save(u);return Map.of("token",jwt.generate(u.getEmail()),"name",u.getName());} @PostMapping("/login") public Map<String,String> login(@RequestBody AuthRequest x){User u=repo.findByEmail(x.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password"));if(!enc.matches(x.password(),u.getPassword()))throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid email or password");return Map.of("token",jwt.generate(u.getEmail()),"name",u.getName());}}
